target.css:
:root {
  --cream: #f5eed8;
  --brown-dark: #3b2a1a;
  --brown-mid: #7a5c3a;
  --brown-light: #c4a97a;
  --accent: #c0392b;
  --badge-bg: #3b2a1a;
  --badge-text: #f5eed8;
  --footer-bg: #e8d9b8;
  --status-bg: #c0392b;
  --status-text: #ffffff;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  margin: 0;
  padding: 20px;
  box-sizing: border-box;
}

.camera-tag {
  background-color: var(--cream);
  border: 2px solid var(--brown-mid);
  border-radius: 10px;
  width: 340px;
  overflow: hidden;
}

.tag-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  background-color: var(--brown-dark);
  border-bottom: 2px solid var(--brown-mid);
}

.tag-icon {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  flex: 1;
}

.tag-label {
  margin: 0;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--brown-light);
  text-transform: uppercase;
}

.tag-name {
  margin: 2px 0 0;
  font-size: 18px;
  font-weight: 700;
  color: var(--cream);
  line-height: 1.1;
}

.tag-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  border: 1.5px solid var(--brown-light);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 4px 8px;
  align-self: flex-start;
}

.tag-details {
  padding: 14px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dashed var(--brown-light);
  padding-bottom: 8px;
}

.detail-row:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.detail-key {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--brown-mid);
}

.detail-val {
  font-size: 14px;
  font-weight: 600;
  color: var(--brown-dark);
}

.detail-val.accent {
  color: var(--accent);
  font-weight: 700;
}

.tag-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 16px;
  background-color: var(--footer-bg);
  border-top: 1.5px solid var(--brown-light);
}

.tag-id {
  font-size: 11px;
  font-weight: 600;
  color: var(--brown-mid);
  letter-spacing: 0.05em;
}

.tag-status {
  background-color: var(--status-bg);
  color: var(--status-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 3px 10px;
  border-radius: 20px;
}

